<?php
require dirname(__DIR__).'/app/bootstrap.php';
$page=(string)($_GET['page']??($user?'dashboard':'login'));$message='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 csrfCheck();$action=(string)($_POST['action']??'');
 if($action==='login'){
  $login=strtolower(trim((string)($_POST['username']??'')));$ip=(string)($_SERVER['REMOTE_ADDR']??'local');
  $buckets=[hash('sha256','ip:'.$ip),hash('sha256','user:'.$login)];$blocked=false;
  foreach($buckets as $bucket){$a=query('SELECT * FROM login_attempts WHERE bucket=?',[$bucket])->fetch();if($a && $a['failures']>=10 && time()-$a['last_at']<900)$blocked=true;}
  if($blocked)$message='Too many attempts. Try again after 15 minutes.';
  else{
   $u=query('SELECT * FROM users WHERE username=? AND enabled=1',[$login])->fetch();
   if($u && password_verify((string)($_POST['password']??''),$u['password'])){session_regenerate_id(true);$_SESSION['uid']=$u['id'];unset($_SESSION['csrf']);foreach($buckets as $b)query('DELETE FROM login_attempts WHERE bucket=?',[$b]);redirect('?page=dashboard');}
   foreach($buckets as $b)query('INSERT INTO login_attempts(bucket,failures,last_at) VALUES(?,1,?) ON CONFLICT(bucket) DO UPDATE SET failures=CASE WHEN last_at<? THEN 1 ELSE failures+1 END,last_at=excluded.last_at',[$b,time(),time()-900]);$message='Username or password was not accepted.';
  }
 }else{
  if(!$user)fail(401,'Login required');
  if($action==='logout'){$_SESSION=[];session_destroy();redirect('?page=login');}
  if($action==='complete'){$s=(string)($_POST['lesson']??'');if(!isset($lessonMap[$s])||!accessible($s))fail(403,'Lesson unavailable');query('INSERT OR IGNORE INTO progress VALUES(?,?,?)',[$user['id'],$s,date('c')]);redirect('?page=lesson&slug='.urlencode($s));}
  if($action==='quiz'){
   $q=(string)($_POST['quiz']??'');if(!isset($quizzes[$q])||($q!=='final'&&!accessible($q)))fail(403,'Quiz unavailable');
   $correct=0;$feedback=[];foreach($quizzes[$q] as $i=>$question){$v=$_POST['a'][$i]??null;$ok=$v!==null&&(string)$v===(string)$question['answer'];$correct+=(int)$ok;$feedback[]=['q'=>$question['q'],'ok'=>$ok,'explanation'=>$question['explanation'],'correct'=>$question['options'][$question['answer']]];}
   $score=(int)round(100*$correct/count($quizzes[$q]));query('INSERT INTO attempts(user_id,quiz,score,created_at) VALUES(?,?,?,?)',[$user['id'],$q,$score,date('c')]);$_SESSION['feedback']=['quiz'=>$q,'score'=>$score,'items'=>$feedback];redirect('?page=quiz&quiz='.urlencode($q));
  }
  if(in_array($action,['create','toggle','reset','access','settings'],true)){
   if(!isAdmin())fail(403,'Admin only');
   if($action==='create'){
    $un=strtolower(trim((string)($_POST['username']??'')));$dn=trim((string)($_POST['display_name']??''));$pw=(string)($_POST['password']??'');
    if(!preg_match('/^[a-z0-9_.-]{3,60}$/',$un)||strlen($dn)<1||strlen($dn)>100||strlen($pw)<12)$message='Use a valid 3–60 character username, name, and a password of at least 12 characters.';
    else {try{query('INSERT INTO users(username,display_name,password,role) VALUES(?,?,?,?)',[$un,$dn,password_hash($pw,PASSWORD_DEFAULT),'student']);$message='Student account created. Share credentials privately.';}catch(PDOException $ex){if($ex->getCode()==='23000')$message='Username already exists.';else throw $ex;}}
   }
   if($action==='toggle'){query("UPDATE users SET enabled=1-enabled WHERE id=? AND role='student'",[(int)($_POST['id']??0)]);$message='Account access updated.';}
   if($action==='reset'){$pw=(string)($_POST['password']??'');if(strlen($pw)<12)$message='Password needs at least 12 characters.';else{query("UPDATE users SET password=? WHERE id=? AND role='student'",[password_hash($pw,PASSWORD_DEFAULT),(int)($_POST['id']??0)]);$message='Password reset. Share it privately.';}}
   if($action==='access'){$s=(string)($_POST['lesson']??'');if(!isset($lessonMap[$s]))fail(400,'Unknown lesson');query('INSERT INTO access VALUES(?,?) ON CONFLICT(lesson) DO UPDATE SET enabled=excluded.enabled',[$s,isset($_POST['enabled'])?1:0]);$message='Lesson access updated.';}
   if($action==='settings'){$v=filter_var($_POST['pass_percent']??null,FILTER_VALIDATE_INT);if($v===false||$v<1||$v>100)fail(400,'Pass percent must be 1–100');query("INSERT INTO settings VALUES('pass_percent',?) ON CONFLICT(name) DO UPDATE SET value=excluded.value",[(string)$v]);$config['pass_percent']=$v;$message='Passing score updated.';}
  }
 }
}
if(!$user && $page!=='login')redirect('?page=login');
if($user && $page==='login')redirect('?page=dashboard');
if($page==='admin'&&!isAdmin())fail(403,'Admin only');
$downloads=[];
foreach(['01_Remote_Control','02_Line_Follower','03_Obstacle_Avoidance'] as $i=>$n)$downloads[$n]=['path'=>'arduino/'.$n.'/'.$n.'.ino','name'=>$n.'.ino','lesson'=>['remote','line','obstacle'][$i]];
foreach(['base','line','obstacle','flow-remote','flow-line','flow-obstacle'] as $n)$downloads['svg-'.$n]=['path'=>'public/assets/svg/'.$n.'.svg','name'=>$n.'.svg','lesson'=>in_array($n,['line','obstacle'])?$n:'wiring'];
foreach($lessons as $l)$downloads['lesson-'.$l['slug']]=['path'=>'content/downloads/'.$l['slug'].'.md','name'=>$l['slug'].'.md','lesson'=>$l['slug']];
$downloads['checklist']=['path'=>'docs/checklists.md','name'=>'checklists.md','lesson'=>'calibration'];$downloads['changelog']=['path'=>'docs/code-changelog.md','name'=>'code-changelog.md','lesson'=>'wiring'];
if($page==='download'){$f=$downloads[(string)($_GET['file']??'')]??null;if(!$f)fail(404,'Unknown download');if(!accessible($f['lesson']))fail(403,'Lesson unavailable');header('Content-Type: application/octet-stream');header('Content-Disposition: attachment; filename="'.$f['name'].'"');readfile($root.'/'.$f['path']);exit;}
$slug=(string)($_GET['slug']??'intro');
if($page==='lesson'&&(!isset($lessonMap[$slug])||!accessible($slug)))fail(404,'Lesson unavailable');
if(!in_array($page,['login','dashboard','lesson','downloads','quiz','progress','certificate','admin'],true))fail(404,'Page not found');
$done=$user?query('SELECT lesson FROM progress WHERE user_id=?',[$user['id']])->fetchAll(PDO::FETCH_COLUMN):[];
$title=$page==='lesson'?$lessonMap[$slug]['title']:ucfirst($page);
function quizForm(string $key):void{global $quizzes;echo '<form method="post">'.csrf().'<input type="hidden" name="action" value="quiz"><input type="hidden" name="quiz" value="'.e($key).'">';foreach($quizzes[$key] as $i=>$q){echo '<fieldset><legend>'.e($q['q']).'</legend>';foreach($q['options'] as $j=>$v)echo '<label><input required type="radio" name="a['.$i.']" value="'.$j.'">'.e($v).'</label>';echo '</fieldset>';}echo '<button>Submit quiz</button></form>';}
