<?php if(!$user): ?><main class="login"><div class="brand">NAVION ROBOTICS</div><p class="eyebrow">LEARN · BUILD · EXPLORE</p><h1>Your robotics journey starts here.</h1><p class="muted">Student learning portal · Grades <?=e($config['grades'])?></p><?php if($message):?><p class="error"><?=e($message)?></p><?php endif ?><form method="post"><?=csrf()?><input type="hidden" name="action" value="login"><label>Username<input name="username" autocomplete="username" required maxlength="60"></label><label>Password<input type="password" name="password" autocomplete="current-password" required></label><button>Sign in to workshop →</button></form><p class="small muted">Your teacher provides your account. Need access or a password reset? Ask your workshop teacher.</p></main>
<?php else: ?><div class="layout"><aside class="sidebar"><div class="brand">NAVION ROBOTICS</div><div class="subbrand">Robotics Workshop</div><nav aria-label="Course navigation"><a href="?page=dashboard" <?=$page==='dashboard'?'class="active"':''?>>◈ &nbsp; My dashboard</a><div class="section">YOUR LEARNING PATH</div><?php foreach($lessons as $i=>$l):if(!accessible($l['slug']))continue;?><a href="?page=lesson&amp;slug=<?=e($l['slug'])?>" <?=$page==='lesson'&&$slug===$l['slug']?'class="active" aria-current="page"':''?>><?=in_array($l['slug'],$done,true)?'✓':sprintf('%02d',$i+1)?> &nbsp;<?=e($l['title'])?></a><?php endforeach ?><div class="section">WORKSHOP TOOLS</div><a href="?page=downloads">Downloads</a><a href="?page=quiz">Final quiz</a><a href="?page=progress">My progress</a><a href="?page=certificate">My certificate</a><?php if(isAdmin()):?><a href="?page=admin">Admin &amp; teacher</a><?php endif ?></nav></aside><main class="main"><header class="top"><span>Workshop / <?=e($title)?></span><span><?=e($user['display_name'])?> · <?=e($user['role'])?></span><form method="post"><?=csrf()?><input type="hidden" name="action" value="logout"><button>Sign out</button></form></header><?php if($message):?><p class="notice"><?=e($message)?></p><?php endif ?>
<?php if($page==='dashboard'):?><div class="eyebrow">YOUR NEXT GREAT IDEA STARTS WITH A SMALL ROBOT</div><h1>Hello, <?=e($user['display_name'])?>.</h1><p class="lead">Build it. Program it. See what happens.</p><section class="hero"><span class="badge">One kit · Three experiments</span><h2>Turn curiosity into movement.</h2><p>Get to know your ESP32 robot, drive it from your laptop, then help it follow a line and find a clear path.</p><?php $next='intro';foreach($lessons as $l){if(accessible($l['slug'])&&!in_array($l['slug'],$done,true)){$next=$l['slug'];break;}}?><a class="button" href="?page=lesson&amp;slug=<?=e($next)?>">Continue learning →</a></section><div class="cards"><div class="card"><div class="number"><?=count($done)?> / <?=count($lessons)?></div><p>Lessons completed</p><progress value="<?=count($done)?>" max="<?=count($lessons)?>" aria-label="Lesson progress"></progress></div><div class="card"><div class="number"><?=query('SELECT COUNT(*) FROM attempts WHERE user_id=?',[$user['id']])->fetchColumn()?></div><p>Quiz attempts saved</p><a href="?page=progress">View your progress →</a></div><div class="card"><span class="badge"><?=eligible((int)$user['id'])?'Ready to print':'In progress'?></span><h3>Your completion certificate</h3><a href="?page=certificate">See requirements →</a></div></div><h2>Meet your three experiments</h2><div class="cards"><?php foreach(['remote'=>'Laptop remote control','line'=>'Follow the line','obstacle'=>'Avoid obstacles'] as $s=>$t):?><article class="card"><span class="eyebrow"><?=e($s)?></span><h3><?=e($t)?></h3><p><?=e($lessonMap[$s]['summary'])?></p><?php if(accessible($s)):?><a href="?page=lesson&amp;slug=<?=e($s)?>">Explore experiment →</a><?php else:?><p>Teacher has not opened this lesson yet.</p><?php endif ?></article><?php endforeach ?></div><p class="small muted">Electrical setup and Windows Bluetooth operation remain prototype assumptions. Follow teacher checks before applying power.</p>
